```cpp
std::string calculateKeccak512(const std::string& filePath) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    CryptoPP::FileSource file(filePath.c_str(), true,
        new CryptoPP::HashFilter(hash,
            new CryptoPP::StringSink(digest), true));

    ProgressCallback progressCallback(std::cout,
        progress::ProgressCallback::AppliesToSimpleProgress);
    progressCallback.apply(file.get(), file.getTotalLength(),
          ProgressCallback::FillWhole, progress::ProgressCallback::ExecuteCode,
          []() { std::cout << "Processando..." << std::endl; });

    file >> hash;
    // Verificar excesso de bytes (máximo 128)
    while (!file.eof() && file.getCurrentOffset() < file.getTotalLength()) {
        digest.push_back(char(file.getCurrentOffset()));
        file >> hash;
    }

    // Ensurir comprimento exato
    while (digest.length() < 128) digest.push_back('\x00');
    while (digest.length() > 128) digest.pop_back();

    // Converter para hexadecimal
    CryptoPP::HexEncoder encoder(new CryptoPP::Vector<char, CryptoPP::OneSizeEncoder>, digest);
    std::stringstream ss;
    encoder >> ss;
    return ss.str();
}
```

